import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define ROWS_PER_BLOCK 32
#define K_TILE 8192
#define SPLIT_K 8
__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K, int kPerSplit) {
    int rowBlock = blockIdx.x;
    int splitIdx = blockIdx.y;
    int rowBase = rowBlock * ROWS_PER_BLOCK;
    int warpId = threadIdx.x / warpSize;
    int lane = threadIdx.x % warpSize;
    int row = rowBase + warpId;
    int kStart = splitIdx * kPerSplit;
    int kEnd = kStart + kPerSplit;
    if (kEnd > K) kEnd = K;
    int localK = kEnd - kStart;
    int localNumChunks = (localK > 0) ? ((localK + K_TILE - 1) / K_TILE) : 0;
    extern __shared__ float sB[]; // 2 * K_TILE floats, double-buffered
    float* sBbuf0 = sB;
    float* sBbuf1 = sB + K_TILE;
    float sum = 0.0f;
    // Preload first chunk of this split into buffer 0
    if (localNumChunks > 0) {
        int chunkStart = kStart;
        int chunkEnd = chunkStart + K_TILE;
        if (chunkEnd > kEnd) chunkEnd = kEnd;
        int chunkLen = chunkEnd - chunkStart;
        if (chunkLen > 0) {
            int chunkLen4 = chunkLen / 4;
            const float4* B4 = reinterpret_cast<const float4*>(B + chunkStart);
            float4* dst4 = reinterpret_cast<float4*>(sBbuf0);
            for (int i = threadIdx.x; i < chunkLen4; i += blockDim.x) {
                dst4[i] = B4[i];
            }
            for (int i = chunkLen4 * 4 + threadIdx.x; i < chunkLen; i += blockDim.x) {
                sBbuf0[i] = B[chunkStart + i];
            }
        }
    }
    __syncthreads();
    for (int chunk = 0; chunk < localNumChunks; chunk++) {
        int curBuf = chunk % 2;
        float* curPtr = (curBuf == 0) ? sBbuf0 : sBbuf1;
        float* nextPtr = (curBuf == 0) ? sBbuf1 : sBbuf0;
        // Issue load of the next chunk into the other buffer; this overlaps
        // with the compute on the current buffer below (software pipelining).
        if (chunk + 1 < localNumChunks) {
            int nChunkStart = kStart + (chunk + 1) * K_TILE;
            int nChunkEnd = nChunkStart + K_TILE;
            if (nChunkEnd > kEnd) nChunkEnd = kEnd;
            int nChunkLen = nChunkEnd - nChunkStart;
            if (nChunkLen > 0) {
                int nChunkLen4 = nChunkLen / 4;
                const float4* B4 = reinterpret_cast<const float4*>(B + nChunkStart);
                float4* dst4 = reinterpret_cast<float4*>(nextPtr);
                for (int i = threadIdx.x; i < nChunkLen4; i += blockDim.x) {
                    dst4[i] = B4[i];
                }
                for (int i = nChunkLen4 * 4 + threadIdx.x; i < nChunkLen; i += blockDim.x) {
                    nextPtr[i] = B[nChunkStart + i];
                }
            }
        }
        int chunkStart = kStart + chunk * K_TILE;
        int chunkEnd = chunkStart + K_TILE;
        if (chunkEnd > kEnd) chunkEnd = kEnd;
        int chunkLen = chunkEnd - chunkStart;
        if (chunkLen > 0 && row < M) {
            int chunkLen4 = chunkLen / 4;
            const float* Arow = A + (size_t)row * K + chunkStart;
            const float4* Arow4 = reinterpret_cast<const float4*>(Arow);
            const float4* sB4 = reinterpret_cast<const float4*>(curPtr);
            int i = lane;
            for (; i + warpSize < chunkLen4; i += warpSize * 2) {
                float4 a0 = Arow4[i];
                float4 b0 = sB4[i];
                float4 a1 = Arow4[i + warpSize];
                float4 b1 = sB4[i + warpSize];
                sum += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
                sum += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
            }
            for (; i < chunkLen4; i += warpSize) {
                float4 a = Arow4[i];
                float4 b = sB4[i];
                sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            }
            for (int i = chunkLen4 * 4 + lane; i < chunkLen; i += warpSize) {
                sum += Arow[i] * curPtr[i];
            }
        }
        // Ensures the load into nextPtr completed before it's read next
        // iteration, and that all warps finished reading curPtr before it
        // gets overwritten two iterations later.
        __syncthreads();
    }
    if (row >= M) return;
    unsigned mask = 0xffffffff;
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum += __shfl_down_sync(mask, sum, offset);
    if (lane == 0) atomicAdd(&C[row], sum);
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());
    int kPerSplit = (K + SPLIT_K - 1) / SPLIT_K;
    int numRowBlocks = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    dim3 grid(numRowBlocks, SPLIT_K);
    int threads = ROWS_PER_BLOCK * 32;
    size_t smem = (size_t)2 * K_TILE * sizeof(float);
    static bool attrSet = false;
    if (!attrSet) {
        cudaFuncSetAttribute(matvec_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
        attrSet = true;
    }
    matvec_kernel<<<grid, threads, smem>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, kPerSplit
    );
    return C;
}
"""

matvec_cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=matvec_cpp_source,
    cuda_sources=matvec_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

